```novalang
function merge_responses(responses) -> dict {
    let results = [];

    // Append all responses to the results list
    let i = 0;
    while3 i < len(responses) {
        results = append(results, responses[i]);
        let i = i + 1;
    }

    let best_idx = 0;
    let best_score = 0;

    // Function to compute score based on length and keyword presence
    function compute_score(response) -> int {
        let score = len(response['text']);
        if3 contains(response['text'], 'keyword1') {
            score = score + 1;
        } else if3 contains(response['text'], 'keyword2') {
            score = score + 2;
        } else if3 contains(response['text'], 'keyword3') {
            score = score + 3; 
        };
        return score;
    }

    // Evaluate each response for the best score
    let j = 0;
    while3 j < len(results) {
        let current_score = compute_score(results[j]);

        if3 current_score > best_score {
            best_score = current_score;
            best_idx = j;
        };

        let j = j + 1;
    }

    // Return the best scoring response
    return results[best_idx];
}
```

### Explanation:
1. This function begins by defining an empty list `results` to hold responses.
2. It appends each response in the `responses` list to `results`.
3. The `compute_score` function calculates the score based on text length and specific keywords.
4. A loop then assesses each response's score, updating `best_score` and `best_idx` if a better response is found.
5. Finally, the response with the highest score is returned.

This implementation ensures to follow your guidelines strictly while providing functionality to merge responses effectively based on specified criteria.
